COMMENT ON TABLE public."app_role" IS '应用角色。用途：定义可分配给账号的角色集合。；一行粒度：一个角色一行；写入者：身份管理服务；读取者：所有应用；来源：管理员配置；生命周期：CORE_MIGRATION；变更策略：CONTROLLED_UPDATE；保留：业务存续期内保留；归档规则在实施前确认。';
COMMENT ON COLUMN public."app_role"."role_id" IS '角色ID。存放：角色稳定身份。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：身份管理服务 / 管理员配置；敏感级别：none；示例：a28ce29f-93bc-5620-a42b-c652824558c9。';
COMMENT ON COLUMN public."app_role"."role_code" IS '角色代码。存放：程序判断使用的唯一不可变代码。；作用：连接账号和权限。；类型：text；允许空：否；默认值：无；键/连接：唯一键；写入来源：身份管理服务 / 管理员配置；敏感级别：none；示例：FINANCE_EDITOR。';
COMMENT ON COLUMN public."app_role"."role_name" IS '角色名称。存放：给管理员阅读的角色名称。；作用：权限配置界面展示。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：身份管理服务 / 管理员配置；敏感级别：none；示例：财务编辑者。';
COMMENT ON COLUMN public."app_role"."description" IS '角色说明。存放：该角色的业务职责和授权边界。；作用：帮助审批者避免过度授权。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：身份管理服务 / 管理员配置；敏感级别：none；示例：可编辑成本卡但不能管理账号。';
COMMENT ON COLUMN public."app_role"."status" IS '状态。存放：ACTIVE 或 RETIRED。；作用：停用角色但保留历史分配记录。；类型：text；允许空：否；默认值：''ACTIVE''；键/连接：无；写入来源：身份管理服务 / 管理员配置；敏感级别：none；示例：ACTIVE。';
COMMENT ON COLUMN public."app_role"."created_at" IS '创建时间。存放：该行首次写入数据库的绝对时间。；作用：用于审计写入先后、排查延迟；不能代替业务发生时间。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：身份管理服务 / 管理员配置；敏感级别：none；示例：2026-08-09T10:30:00+08:00。';
COMMENT ON COLUMN public."app_role"."updated_at" IS '最后更新时间。存放：该行最后一次被允许修改的绝对时间。；作用：用于增量同步和并发检查；事实发生时间仍应使用专门字段。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：身份管理服务 / 管理员配置；敏感级别：none；示例：2026-08-09T11:05:00+08:00。';
COMMENT ON CONSTRAINT "pk_app_role__role_id" ON public."app_role" IS 'Primary key for the declared one-row grain of app_role.';
COMMENT ON CONSTRAINT "uq_app_role__role_code" ON public."app_role" IS 'Declared ordinary UNIQUE business key on app_role (role_code).';
COMMENT ON CONSTRAINT "ck_app_role__status__01" ON public."app_role" IS 'Fail-closed model CHECK field:status#1: status IN (''ACTIVE'',''RETIRED'')';
COMMENT ON TABLE public."app_schema_migration" IS '迁移版本台账。用途：按代码仓库分别记录已执行的迁移，消除多个项目共用单一数字版本造成的冲突。；一行粒度：代码仓库 × 迁移版本一行；写入者：受控迁移执行器；读取者：所有项目；来源：各项目迁移目录；生命周期：CORE_MIGRATION；变更策略：APPEND_ONLY；保留：永久保留。';
COMMENT ON COLUMN public."app_schema_migration"."migration_id" IS '迁移记录ID。存放：迁移台账内部稳定主键。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：受控迁移执行器 / 各项目迁移目录；敏感级别：none；示例：0b420e40-94f8-52d9-b68d-d70324833cc1。';
COMMENT ON COLUMN public."app_schema_migration"."repository_code" IS '代码仓库代码。存放：产生这条迁移的代码仓库稳定代码。；作用：与 migration_version 共同唯一，避免不同仓库版本号碰撞。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：受控迁移执行器 / 各项目迁移目录；敏感级别：none；示例：bakery_ops。';
COMMENT ON COLUMN public."app_schema_migration"."migration_version" IS '迁移版本。存放：仓库内部不可重复的迁移版本。；作用：按原仓库顺序判断遗漏和重复执行。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：受控迁移执行器 / 各项目迁移目录；敏感级别：none；示例：00109。';
COMMENT ON COLUMN public."app_schema_migration"."migration_name" IS '迁移名称。存放：来源台账记录的人类可读迁移标题；来源没有时为空。；作用：承接旧 schema_migrations.name，帮助人工审计，但不参与版本唯一性。；类型：text；允许空：是；默认值：无；键/连接：无；写入来源：受控迁移执行器 / 各项目迁移目录；敏感级别：none；示例：add margin and holiday factor。';
COMMENT ON COLUMN public."app_schema_migration"."filename" IS '迁移文件名。存放：实际执行的迁移文件名。；作用：便于从数据库追溯到版本库文件。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：受控迁移执行器 / 各项目迁移目录；敏感级别：none；示例：109_margin_and_holiday_factor.sql。';
COMMENT ON COLUMN public."app_schema_migration"."checksum_sha256" IS '文件校验值。存放：迁移文件内容的 SHA-256。；作用：阻止同一版本号对应不同 SQL 内容。；类型：char(64)；允许空：否；默认值：无；键/连接：无；写入来源：受控迁移执行器 / 各项目迁移目录；敏感级别：none；示例：d7a8...64位十六进制。';
COMMENT ON COLUMN public."app_schema_migration"."applied_at" IS '执行时间。存放：迁移成功提交的时间。；作用：用于排序、审计和避开生产抓取窗口。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：受控迁移执行器 / 各项目迁移目录；敏感级别：none；示例：2026-08-09T02:15:00+08:00。';
COMMENT ON COLUMN public."app_schema_migration"."applied_by" IS '执行主体。存放：执行迁移的人或自动化身份。；作用：明确谁完成了生产变更。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：受控迁移执行器 / 各项目迁移目录；敏感级别：none；示例：human:weiliang。';
COMMENT ON COLUMN public."app_schema_migration"."execution_ms" IS '执行耗时毫秒。存放：迁移事务的实际耗时。；作用：识别慢 DDL 和锁风险。；类型：integer；允许空：是；默认值：无；键/连接：无；写入来源：受控迁移执行器 / 各项目迁移目录；敏感级别：none；示例：842。';
COMMENT ON CONSTRAINT "pk_app_schema_migration__migration_id" ON public."app_schema_migration" IS 'Primary key for the declared one-row grain of app_schema_migration.';
COMMENT ON CONSTRAINT "uq_app_schema_migration__repository_code__migration_version" ON public."app_schema_migration" IS 'Declared ordinary UNIQUE business key on app_schema_migration (repository_code, migration_version).';
COMMENT ON CONSTRAINT "ck_app_schema_migration__table__01" ON public."app_schema_migration" IS 'Fail-closed model CHECK table#1: execution_ms IS NULL OR execution_ms >= 0';
COMMENT ON TABLE public."app_session" IS '登录会话。用途：保存经过哈希的登录会话及其过期和撤销状态。；一行粒度：一个登录会话一行；写入者：身份管理服务；读取者：所有应用；来源：成功认证；生命周期：CORE_MIGRATION；变更策略：CONTROLLED_UPDATE_UNTIL_TERMINAL；保留：过期或撤销后保留 90 天，再按审计政策清理。备注：签发后除首次写入 revoked_at 外全部字段冻结；过期或撤销即终态。APPEND_ONLY 无法表达登出撤销，因此明确采用终态前受控更新。';
COMMENT ON COLUMN public."app_session"."session_id" IS '会话ID。存放：会话稳定主键；客户端令牌使用另一随机值。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：身份管理服务 / 成功认证；敏感级别：none；示例：4cfb5a49-e2e6-5ad7-b79b-03d1d80a73c6。';
COMMENT ON COLUMN public."app_session"."user_id" IS '账号ID。存放：会话所属账号。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：无；键/连接：外键->app_user.user_id（WITH_TABLE）；写入来源：身份管理服务 / 成功认证；敏感级别：none；示例：869c8106-7e07-5851-a6ff-d68b3a2030c3。';
COMMENT ON COLUMN public."app_session"."token_hash" IS '会话令牌哈希。存放：客户端会话令牌的 SHA-256，数据库不保存原令牌。；作用：验证会话同时降低数据库泄漏后直接冒用风险。；类型：char(64)；允许空：否；默认值：无；键/连接：唯一键；写入来源：身份管理服务 / 成功认证；敏感级别：secret；示例：0f4c...64位十六进制。';
COMMENT ON COLUMN public."app_session"."issued_at" IS '签发时间。存放：会话创建时间。；作用：计算生命周期。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：身份管理服务 / 成功认证；敏感级别：none；示例：2026-08-09T09:00:00+08:00。';
COMMENT ON COLUMN public."app_session"."expires_at" IS '过期时间。存放：会话自动失效时间。；作用：每次鉴权必须检查。；类型：timestamptz；允许空：否；默认值：无；键/连接：无；写入来源：身份管理服务 / 成功认证；敏感级别：none；示例：2026-08-09T21:00:00+08:00。';
COMMENT ON COLUMN public."app_session"."revoked_at" IS '撤销时间。存放：登出或管理员撤销会话的时间。；作用：保留审计而不立即删除。；类型：timestamptz；允许空：是；默认值：无；键/连接：无；写入来源：身份管理服务 / 成功认证；敏感级别：none；示例：2026-08-09T12:00:00+08:00。';
COMMENT ON COLUMN public."app_session"."ip_address" IS '签发IP。存放：签发会话时的请求 IP。；作用：用于异常会话分析，访问受限。；类型：inet；允许空：是；默认值：无；键/连接：无；写入来源：身份管理服务 / 成功认证；敏感级别：restricted；示例：203.0.113.10。';
COMMENT ON COLUMN public."app_session"."user_agent" IS '客户端标识。存放：签发会话时的客户端摘要。；作用：辅助识别被盗会话。；类型：text；允许空：是；默认值：无；键/连接：无；写入来源：身份管理服务 / 成功认证；敏感级别：internal；示例：Safari/macOS。';
COMMENT ON CONSTRAINT "pk_app_session__session_id" ON public."app_session" IS 'Primary key for the declared one-row grain of app_session.';
COMMENT ON CONSTRAINT "uq_app_session__token_hash" ON public."app_session" IS 'Declared ordinary UNIQUE business key on app_session (token_hash).';
COMMENT ON CONSTRAINT "ck_app_session__table__01" ON public."app_session" IS 'Fail-closed model CHECK table#1: expires_at > issued_at';
COMMENT ON TABLE public."app_source_system" IS '来源系统注册表。用途：登记 RES、Lark、财务模板、人工后台等数据来源及其责任边界。；一行粒度：每个可区分的数据来源系统一行；写入者：平台管理员；读取者：所有项目；来源：人工配置；生命周期：CORE_MIGRATION；变更策略：CONTROLLED_UPDATE；保留：永久保留；停用来源仅改状态。';
COMMENT ON COLUMN public."app_source_system"."source_system_id" IS '来源系统ID。存放：来源系统稳定身份。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：平台管理员 / 人工配置；敏感级别：none；示例：7996d63a-5925-5972-9ea2-b51d0882c497。';
COMMENT ON COLUMN public."app_source_system"."source_code" IS '来源代码。存放：程序和数据字典使用的不可变代码。；作用：作为来源身份、批次和审计表的统一连接键。；类型：text；允许空：否；默认值：无；键/连接：唯一键；写入来源：平台管理员 / 人工配置；敏感级别：none；示例：res_pos。';
COMMENT ON COLUMN public."app_source_system"."source_name" IS '来源名称。存放：给人阅读的来源系统名称。；作用：用于界面和审计展示，不参与业务连接。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：平台管理员 / 人工配置；敏感级别：none；示例：Restosuite POS。';
COMMENT ON COLUMN public."app_source_system"."source_type" IS '来源类型。存放：来源属于 API、FILE、MANUAL、DATABASE 或 GENERATED。；作用：决定抓取、校验和重跑策略。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：平台管理员 / 人工配置；敏感级别：none；示例：API。';
COMMENT ON COLUMN public."app_source_system"."owner_project" IS '责任项目。存放：负责读取该来源并写入规范表的唯一项目。；作用：阻止多个项目争抢同一来源写入权。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：平台管理员 / 人工配置；敏感级别：none；示例：res_api。';
COMMENT ON COLUMN public."app_source_system"."authoritative_scope" IS '权威范围。存放：该来源在哪些事实上具备权威性。；作用：防止把财务月表、POS 日表或人工确认互相冒充。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：平台管理员 / 人工配置；敏感级别：none；示例：POS销售与会员事实。';
COMMENT ON COLUMN public."app_source_system"."status" IS '状态。存放：来源是否 ACTIVE、PAUSED 或 RETIRED。；作用：控制调度和告警，但不删除历史。；类型：text；允许空：否；默认值：''ACTIVE''；键/连接：无；写入来源：平台管理员 / 人工配置；敏感级别：none；示例：ACTIVE。';
COMMENT ON COLUMN public."app_source_system"."created_at" IS '创建时间。存放：该行首次写入数据库的绝对时间。；作用：用于审计写入先后、排查延迟；不能代替业务发生时间。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：平台管理员 / 人工配置；敏感级别：none；示例：2026-08-09T10:30:00+08:00。';
COMMENT ON COLUMN public."app_source_system"."updated_at" IS '最后更新时间。存放：该行最后一次被允许修改的绝对时间。；作用：用于增量同步和并发检查；事实发生时间仍应使用专门字段。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：平台管理员 / 人工配置；敏感级别：none；示例：2026-08-09T11:05:00+08:00。';
COMMENT ON CONSTRAINT "pk_app_source_system__source_system_id" ON public."app_source_system" IS 'Primary key for the declared one-row grain of app_source_system.';
COMMENT ON CONSTRAINT "uq_app_source_system__source_code" ON public."app_source_system" IS 'Declared ordinary UNIQUE business key on app_source_system (source_code).';
COMMENT ON CONSTRAINT "ck_app_source_system__table__01" ON public."app_source_system" IS 'Fail-closed model CHECK table#1: source_system_id <> ''00000000-0000-0000-0000-000000000000''';
COMMENT ON CONSTRAINT "ck_app_source_system__source_type__01" ON public."app_source_system" IS 'Fail-closed model CHECK field:source_type#1: source_type IN (''API'',''FILE'',''MANUAL'',''DATABASE'',''GENERATED'')';
COMMENT ON CONSTRAINT "ck_app_source_system__status__01" ON public."app_source_system" IS 'Fail-closed model CHECK field:status#1: status IN (''ACTIVE'',''PAUSED'',''RETIRED'')';
COMMENT ON TABLE public."app_unit" IS '统一计量单位。用途：登记产品、原料、配方、采购和库存共同使用的计量单位；单位代码只表达计量含义，不夹带某个供应商包装规格。；一行粒度：一个受控计量单位一行；写入者：数据治理管理员；读取者：BakeryOps、财务网站、RES/POS、分析/BI；来源：企业单位字典和人工批准；生命周期：CORE_MIGRATION；变更策略：CONTROLLED_UPDATE；保留：永久保留；已引用单位不得物理删除。备注：全局可换算单位使用 canonical_unit_id + factor_to_canonical；供应商包装或特定原料换算使用 scm_material_unit_conversion。';
COMMENT ON COLUMN public."app_unit"."unit_id" IS '单位ID。存放：跨产品、原料、配方、采购和库存使用的稳定计量单位身份。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：数据治理管理员 / 企业单位字典和人工批准；敏感级别：none；示例：3cf62aa7-6657-5f04-b833-b7d7163ad827。';
COMMENT ON COLUMN public."app_unit"."unit_code" IS '单位代码。存放：程序使用的唯一、大小写受控单位代码。；作用：替代散落的 g、G、gram、公斤等自由文本。；类型：text；允许空：否；默认值：无；键/连接：唯一键；写入来源：数据治理管理员 / 企业单位字典和人工批准；敏感级别：none；示例：G。';
COMMENT ON COLUMN public."app_unit"."unit_name" IS '单位名称。存放：给业务人员阅读的单位名称。；作用：用于界面展示，连接仍使用 unit_id。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：数据治理管理员 / 企业单位字典和人工批准；敏感级别：none；示例：克。';
COMMENT ON COLUMN public."app_unit"."dimension_code" IS '量纲代码。存放：MASS、VOLUME、COUNT、LENGTH、PACKAGING 或 OTHER。；作用：阻止质量、体积、件数等不同量纲直接换算。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：数据治理管理员 / 企业单位字典和人工批准；敏感级别：none；示例：MASS。';
COMMENT ON COLUMN public."app_unit"."canonical_unit_id" IS '量纲基准单位ID。存放：同量纲的企业基准单位；包装等只能按具体物料换算时可以为空。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：是；默认值：无；键/连接：外键->app_unit.unit_id（WITH_TABLE）；写入来源：数据治理管理员 / 企业单位字典和人工批准；敏感级别：none；示例：97dcea12-9b77-54a7-92b9-bbef1a85877e。';
COMMENT ON COLUMN public."app_unit"."factor_to_canonical" IS '换算到基准单位系数。存放：一个本单位等于多少个 canonical_unit_id；没有全局线性换算时为空。；作用：支持 kg→g、L→ml 等全局换算；CASE→g 等物料相关换算不得写这里。；类型：numeric(24,12)；允许空：是；默认值：无；键/连接：无；写入来源：数据治理管理员 / 企业单位字典和人工批准；敏感级别：none；示例：1000.000000000000。';
COMMENT ON COLUMN public."app_unit"."decimal_scale" IS '建议小数位。存放：该单位业务录入和展示建议保留的小数位。；作用：统一界面精度；不替代金额和计算精度规则。；类型：smallint；允许空：否；默认值：3；键/连接：无；写入来源：数据治理管理员 / 企业单位字典和人工批准；敏感级别：none；示例：3。';
COMMENT ON COLUMN public."app_unit"."status" IS '单位状态。存放：ACTIVE 或 RETIRED。；作用：停用单位但不破坏历史事实。；类型：text；允许空：否；默认值：''ACTIVE''；键/连接：无；写入来源：数据治理管理员 / 企业单位字典和人工批准；敏感级别：none；示例：ACTIVE。';
COMMENT ON COLUMN public."app_unit"."created_by_user_id" IS '创建账号。存放：触发该次人工或受控系统写入的应用账号。自动任务可以为空并由 job_run_id 追踪。；作用：区分谁确认了业务事实与哪个服务实际执行 SQL。；类型：uuid；允许空：是；默认值：无；键/连接：外键->app_user.user_id（WITH_TABLE）；写入来源：数据治理管理员 / 企业单位字典和人工批准；敏感级别：internal；示例：018f7f12-7c40-7dc1-a2ac-4a7924c60b21。';
COMMENT ON COLUMN public."app_unit"."created_at" IS '创建时间。存放：该行首次写入数据库的绝对时间。；作用：用于审计写入先后、排查延迟；不能代替业务发生时间。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：数据治理管理员 / 企业单位字典和人工批准；敏感级别：none；示例：2026-08-09T10:30:00+08:00。';
COMMENT ON COLUMN public."app_unit"."updated_at" IS '最后更新时间。存放：该行最后一次被允许修改的绝对时间。；作用：用于增量同步和并发检查；事实发生时间仍应使用专门字段。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：数据治理管理员 / 企业单位字典和人工批准；敏感级别：none；示例：2026-08-09T11:05:00+08:00。';
COMMENT ON CONSTRAINT "pk_app_unit__unit_id" ON public."app_unit" IS 'Primary key for the declared one-row grain of app_unit.';
COMMENT ON CONSTRAINT "uq_app_unit__unit_code" ON public."app_unit" IS 'Declared ordinary UNIQUE business key on app_unit (unit_code).';
COMMENT ON CONSTRAINT "ck_app_unit__table__01" ON public."app_unit" IS 'Fail-closed model CHECK table#1: canonical_unit_id IS NULL OR canonical_unit_id <> unit_id';
COMMENT ON CONSTRAINT "ck_app_unit__dimension_code__01" ON public."app_unit" IS 'Fail-closed model CHECK field:dimension_code#1: dimension_code IN (''MASS'',''VOLUME'',''COUNT'',''LENGTH'',''PACKAGING'',''OTHER'')';
COMMENT ON CONSTRAINT "ck_app_unit__factor_to_canonical__01" ON public."app_unit" IS 'Fail-closed model CHECK field:factor_to_canonical#1: factor_to_canonical IS NULL OR factor_to_canonical > 0';
COMMENT ON CONSTRAINT "ck_app_unit__decimal_scale__01" ON public."app_unit" IS 'Fail-closed model CHECK field:decimal_scale#1: decimal_scale BETWEEN 0 AND 12';
COMMENT ON CONSTRAINT "ck_app_unit__status__01" ON public."app_unit" IS 'Fail-closed model CHECK field:status#1: status IN (''ACTIVE'',''RETIRED'')';
COMMENT ON TABLE public."app_user" IS '统一应用账号。用途：统一财务、BakeryOps及未来后台的登录账号；不等同于员工自然人。；一行粒度：每个可登录或可代表服务的账号一行；写入者：身份管理服务；读取者：所有应用；来源：管理员创建、单点登录或服务账号配置；生命周期：CORE_MIGRATION；变更策略：CONTROLLED_UPDATE；保留：账号停用后保留审计所需最短期限，不物理删除被审计引用的账号。备注：failed_login_count 和 last_login_at 是认证路径必须原子读取/更新的安全状态缓存，不是分析事实；notification_subscription_codes 是消息路由需要读取的当前偏好集合，不代表权限或雇佣岗位，更新必须校验已登记消息类型并写 app_audit_event；人员出勤绝不能读取这些账号状态字段。';
COMMENT ON COLUMN public."app_user"."user_id" IS '账号ID。存放：应用账号稳定身份。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：none；示例：869c8106-7e07-5851-a6ff-d68b3a2030c3。';
COMMENT ON COLUMN public."app_user"."person_id" IS '人员ID。存放：账号对应自然人；服务账号可以为空。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：是；默认值：无；键/连接：外键->hr_person.person_id（WITH_TABLE）；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：none；示例：974372c0-eeaf-573e-b810-7959c45598c9。';
COMMENT ON COLUMN public."app_user"."username" IS '登录名。存放：唯一、大小写不敏感的登录名。；作用：供密码或内部登录使用；不得用作人员跨域主键。；类型：citext；允许空：否；默认值：无；键/连接：唯一键；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：internal；示例：finance.admin。';
COMMENT ON COLUMN public."app_user"."display_name" IS '显示名称。存放：界面显示的账号名称。；作用：提高审计可读性。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：none；示例：Finance Admin。';
COMMENT ON COLUMN public."app_user"."password_hash" IS '密码哈希。存放：采用批准算法生成的密码哈希；单点登录账号可以为空。；作用：仅用于认证，绝不保存明文密码。；类型：text；允许空：是；默认值：无；键/连接：无；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：secret；示例：$argon2id$...。';
COMMENT ON COLUMN public."app_user"."account_type" IS '账号类型。存放：HUMAN 或 SERVICE。；作用：决定会话、MFA和权限审查策略。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：none；示例：HUMAN。';
COMMENT ON COLUMN public."app_user"."status" IS '账号状态。存放：ACTIVE、LOCKED、DISABLED 或 PENDING_RESET。；作用：阻止失效账号继续创建会话。；类型：text；允许空：否；默认值：''ACTIVE''；键/连接：无；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：none；示例：ACTIVE。';
COMMENT ON COLUMN public."app_user"."must_change_password" IS '强制改密。存放：下次密码登录是否必须先修改密码。；作用：处理初始密码和安全重置。；类型：boolean；允许空：否；默认值：false；键/连接：无；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：none；示例：false。';
COMMENT ON COLUMN public."app_user"."failed_login_count" IS '连续失败次数。存放：自上次成功登录后的连续失败次数。；作用：达到门槛后锁定账号。；类型：integer；允许空：否；默认值：0；键/连接：无；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：none；示例：0。';
COMMENT ON COLUMN public."app_user"."last_login_at" IS '最后登录时间。存放：最近一次成功认证时间。；作用：用于账号审查，不作为员工出勤。；类型：timestamptz；允许空：是；默认值：无；键/连接：无；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：internal；示例：2026-08-09T09:00:00+08:00。';
COMMENT ON COLUMN public."app_user"."notification_subscription_codes" IS '消息订阅代码。存放：该账号主动保留的自动推送类型代码集合；空数组表示当前不订阅任何自动推送。；作用：承接现有 staff.subscriptions，并让消息任务按稳定 user_id 选择收件人；这是不可从角色或消息历史确定性重建的当前偏好状态。；类型：text[]；允许空：否；默认值：''{}''::text[]；键/连接：无；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：internal；示例：{DAILY_REVIEW,PRODUCTION_PLAN}。误用提示/备注：只能通过受控偏好更新函数写入；每个代码必须存在于部署随附的消息类型注册表，函数拒绝未知代码和重复代码。变更历史写 app_audit_event，不把数组拆成分析事实。';
COMMENT ON COLUMN public."app_user"."created_at" IS '创建时间。存放：该行首次写入数据库的绝对时间。；作用：用于审计写入先后、排查延迟；不能代替业务发生时间。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：none；示例：2026-08-09T10:30:00+08:00。';
COMMENT ON COLUMN public."app_user"."updated_at" IS '最后更新时间。存放：该行最后一次被允许修改的绝对时间。；作用：用于增量同步和并发检查；事实发生时间仍应使用专门字段。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：身份管理服务 / 管理员创建、单点登录或服务账号配置；敏感级别：none；示例：2026-08-09T11:05:00+08:00。';
COMMENT ON CONSTRAINT "pk_app_user__user_id" ON public."app_user" IS 'Primary key for the declared one-row grain of app_user.';
COMMENT ON CONSTRAINT "uq_app_user__username" ON public."app_user" IS 'Declared ordinary UNIQUE business key on app_user (username).';
COMMENT ON CONSTRAINT "ck_app_user__account_type__01" ON public."app_user" IS 'Fail-closed model CHECK field:account_type#1: account_type IN (''HUMAN'',''SERVICE'')';
COMMENT ON CONSTRAINT "ck_app_user__status__01" ON public."app_user" IS 'Fail-closed model CHECK field:status#1: status IN (''ACTIVE'',''LOCKED'',''DISABLED'',''PENDING_RESET'')';
COMMENT ON CONSTRAINT "ck_app_user__failed_login_count__01" ON public."app_user" IS 'Fail-closed model CHECK field:failed_login_count#1: failed_login_count >= 0';
COMMENT ON CONSTRAINT "ck_app_user__notification_subscription_codes__01" ON public."app_user" IS 'Fail-closed model CHECK field:notification_subscription_codes#1: cardinality(notification_subscription_codes) <= 64';
COMMENT ON CONSTRAINT "ck_app_user__notification_subscription_codes__02" ON public."app_user" IS 'Fail-closed model CHECK field:notification_subscription_codes#2: array_position(notification_subscription_codes, NULL) IS NULL';
COMMENT ON TABLE public."app_user_location_scope" IS '账号地点范围。用途：限制一项账号角色分配可以读取或操作哪些门店、厨房或仓库，避免多角色账号的地点范围互相串用。；一行粒度：账号角色分配 × 地点 × 权限范围一行；写入者：身份管理服务；读取者：所有应用；来源：管理员授权；生命周期：CORE_MIGRATION；变更策略：CONTROLLED_UPDATE_UNTIL_TERMINAL；保留：业务存续期内保留；归档规则在实施前确认。备注：授予后仅允许补写 revoked_at 或受控缩短 valid_to；账号角色分配、地点、级别和起点冻结，所有修改进入 app_audit_event。当前 app_user_store_scope 迁移时先建立账号当时有效的 app_user_role，再把门店范围挂到具体 user_role_id；不得把一个地点范围默认扩散到账号的所有角色。';
COMMENT ON COLUMN public."app_user_location_scope"."user_location_scope_id" IS '范围ID。存放：地点授权稳定主键。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：身份管理服务 / 管理员授权；敏感级别：none；示例：2052c96f-75af-54a3-8208-2fe3f1bed7dd。';
COMMENT ON COLUMN public."app_user_location_scope"."user_role_id" IS '账号角色分配ID。存放：被限定地点范围的具体账号角色分配；同一账号有多个角色时必须分别授权。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：无；键/连接：外键->app_user_role.user_role_id（WITH_TABLE）；写入来源：身份管理服务 / 管理员授权；敏感级别：none；示例：b77e0323-5e3c-539d-aa15-06b42b91400d。';
