COMMENT ON CONSTRAINT "ck_mkt_reward_claim__table__01" ON public."mkt_reward_claim" IS 'Fail-closed model CHECK table#1: expires_at IS NULL OR (reserved_at IS NOT NULL AND expires_at > reserved_at)';
COMMENT ON CONSTRAINT "ck_mkt_reward_claim__table__02" ON public."mkt_reward_claim" IS 'Fail-closed model CHECK table#2: (source_system_id IS NULL) = (source_fulfillment_id IS NULL)';
