COMMENT ON CONSTRAINT "ck_mkt_reward_claim__table__04" ON public."mkt_reward_claim" IS 'Fail-closed model CHECK table#4: status <> ''REDEEMED'' OR redeemed_at IS NOT NULL';
COMMENT ON CONSTRAINT "ck_mkt_reward_claim__quantity__01" ON public."mkt_reward_claim" IS 'Fail-closed model CHECK field:quantity#1: quantity > 0';
COMMENT ON CONSTRAINT "ck_mkt_reward_claim__status__01" ON public."mkt_reward_claim" IS 'Fail-closed model CHECK field:status#1: status IN (''RESERVED'',''REDEEMED'',''EXPIRED'',''CANCELLED'',''REJECTED'')';
COMMENT ON CONSTRAINT "ck_mkt_reward_claim__source_fulfillment_id__01" ON public."mkt_reward_claim" IS 'Fail-closed model CHECK field:source_fulfillment_id#1: source_fulfillment_id IS NULL OR btrim(source_fulfillment_id) <> ''''';
COMMENT ON TABLE public."mkt_reward_stock" IS '活动奖励库存。用途：保存活动版本、地点和奖励的可用、预留和已发数量。；一行粒度：活动版本 × 地点 × 奖励一行；写入者：HBTI/营销库存服务；读取者：HBTI、财务网站、分析/BI；来源：营销分配和奖励发放；生命周期：CORE_MIGRATION；变更策略：CONTROLLED_WORKFLOW；保留：业务存续期内保留；归档规则在实施前确认。备注：unit_cost_estimate 是活动分配时不可反推的批准预算快照，因此放在本粒度，不放奖励主档；没有成本时 currency 也必须为空。四个数量虽可由分配/领取事实核算，但本表是并发预留的事务控制行，不是分析快照；更新必须使用 version_no 乐观锁并与有 reward_stock_id 的 reward_claim 同事务。stockless 外部履约不扣本表库存。v_mkt_reward_stock_reconciliation 持续检查缓存计数与有库存领取事实是否漂移。';
COMMENT ON COLUMN public."mkt_reward_stock"."reward_stock_id" IS '奖励库存ID。存放：一条活动奖励库存稳定主键。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：HBTI/营销库存服务 / 营销分配和奖励发放；敏感级别：none；示例：7173f2bb-2398-525d-acea-8023de261b97。';
COMMENT ON COLUMN public."mkt_reward_stock"."campaign_version_id" IS '活动版本ID。存放：库存分配给的活动版本。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：无；键/连接：外键->mkt_campaign_version.campaign_version_id（WITH_TABLE）；写入来源：HBTI/营销库存服务 / 营销分配和奖励发放；敏感级别：none；示例：37505ac6-358a-51de-8460-d3d06cda0ca3。';
COMMENT ON COLUMN public."mkt_reward_stock"."location_id" IS '地点ID。存放：奖励可领取地点；数字权益可为空。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：是；默认值：无；键/连接：外键->ops_location.location_id（WITH_TABLE）；写入来源：HBTI/营销库存服务 / 营销分配和奖励发放；敏感级别：none；示例：23e9d2d4-f525-5e85-9e18-ad25aadb718c。';
