COMMENT ON CONSTRAINT "ck_mkt_survey_question__question_type__01" ON public."mkt_survey_question" IS 'Fail-closed model CHECK field:question_type#1: question_type IN (''SINGLE_CHOICE'',''MULTIPLE_CHOICE'',''RATING'',''TEXT'',''BOOLEAN'')';
COMMENT ON CONSTRAINT "ck_mkt_survey_question__sequence_no__01" ON public."mkt_survey_question" IS 'Fail-closed model CHECK field:sequence_no#1: sequence_no > 0';
COMMENT ON TABLE public."mkt_survey_question_option" IS '问卷选项。用途：保存选择题选项代码、文本、顺序和可选分析标签。；一行粒度：题目 × 选项代码一行；写入者：营销/HBTI后台；读取者：HBTI、分析/BI；来源：活动问卷配置；生命周期：CORE_MIGRATION；变更策略：DRAFT_MUTABLE_THEN_FROZEN；保留：业务存续期内保留；归档规则在实施前确认。备注：所属 campaign_version 处于 DRAFT 时可编辑；发布后选项冻结，避免历史答案连接到被改写的选项。';
COMMENT ON COLUMN public."mkt_survey_question_option"."survey_question_option_id" IS '选项ID。存放：一条题目选项稳定身份。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：营销/HBTI后台 / 活动问卷配置；敏感级别：none；示例：dceeb00b-942e-5cf3-9a17-bf60e9d81f6f。';
COMMENT ON COLUMN public."mkt_survey_question_option"."survey_question_id" IS '题目ID。存放：选项所属题目。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：无；键/连接：外键->mkt_survey_question.survey_question_id（WITH_TABLE）；写入来源：营销/HBTI后台 / 活动问卷配置；敏感级别：none；示例：1b6a01ed-214b-54ba-a71f-5763c3f06057。';
COMMENT ON COLUMN public."mkt_survey_question_option"."option_code" IS '选项代码。存放：题目内稳定选项代码。；作用：答案连接和跨语言分析。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：营销/HBTI后台 / 活动问卷配置；敏感级别：none；示例：DARK_CHOCOLATE。';
COMMENT ON COLUMN public."mkt_survey_question_option"."option_text" IS '选项文本。存放：会员看到的选项文本。；作用：保留发布内容。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：营销/HBTI后台 / 活动问卷配置；敏感级别：none；示例：黑巧克力。';
COMMENT ON COLUMN public."mkt_survey_question_option"."sequence_no" IS '选项顺序。存放：题目内展示顺序。；作用：重现交互。；类型：integer；允许空：否；默认值：无；键/连接：无；写入来源：营销/HBTI后台 / 活动问卷配置；敏感级别：none；示例：1。';
COMMENT ON COLUMN public."mkt_survey_question_option"."analysis_tags" IS '分析标签。存放：批准的产品偏好或分群标签。；作用：避免后续从自由文本猜标签。；类型：text[]；允许空：否；默认值：''{}''::text[]；键/连接：无；写入来源：营销/HBTI后台 / 活动问卷配置；敏感级别：none；示例：{chocolate,dark}。';
COMMENT ON COLUMN public."mkt_survey_question_option"."created_by_user_id" IS '创建账号。存放：触发该次人工或受控系统写入的应用账号。自动任务可以为空并由 job_run_id 追踪。；作用：区分谁确认了业务事实与哪个服务实际执行 SQL。；类型：uuid；允许空：是；默认值：无；键/连接：外键->app_user.user_id（WITH_TABLE）；写入来源：营销/HBTI后台 / 活动问卷配置；敏感级别：internal；示例：018f7f12-7c40-7dc1-a2ac-4a7924c60b21。';
COMMENT ON COLUMN public."mkt_survey_question_option"."created_at" IS '创建时间。存放：该行首次写入数据库的绝对时间。；作用：用于审计写入先后、排查延迟；不能代替业务发生时间。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：营销/HBTI后台 / 活动问卷配置；敏感级别：none；示例：2026-08-09T10:30:00+08:00。';
COMMENT ON COLUMN public."mkt_survey_question_option"."updated_at" IS '最后更新时间。存放：该行最后一次被允许修改的绝对时间。；作用：用于增量同步和并发检查；事实发生时间仍应使用专门字段。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：营销/HBTI后台 / 活动问卷配置；敏感级别：none；示例：2026-08-09T11:05:00+08:00。';
COMMENT ON CONSTRAINT "pk_mkt_survey_question_option__survey_question_option_id" ON public."mkt_survey_question_option" IS 'Primary key for the declared one-row grain of mkt_survey_question_option.';
COMMENT ON CONSTRAINT "uq_mkt_survey_question_option__survey_question_id__option_code" ON public."mkt_survey_question_option" IS 'Declared ordinary UNIQUE business key on mkt_survey_question_option (survey_question_id, option_code).';
COMMENT ON CONSTRAINT "uq_mkt_survey_question_option__survey_question_id__sequence_no" ON public."mkt_survey_question_option" IS 'Declared ordinary UNIQUE business key on mkt_survey_question_option (survey_question_id, sequence_no).';
COMMENT ON CONSTRAINT "ck_mkt_survey_question_option__sequence_no__01" ON public."mkt_survey_question_option" IS 'Fail-closed model CHECK field:sequence_no#1: sequence_no > 0';
COMMENT ON TABLE public."mkt_survey_response" IS '问卷作答。用途：保存会员对某活动版本的一次完整、部分或仅有历史结果锚点的问卷尝试。；一行粒度：活动会员 × 尝试次数一行；写入者：HBTI应用；读取者：HBTI、分析/BI；来源：会员提交；生命周期：CORE_MIGRATION；变更策略：CONTROLLED_UPDATE_UNTIL_TERMINAL；保留：业务存续期内保留；归档规则在实施前确认。备注：新作答必须记录真实 started_at、真实来源作答ID和正数 attempt_no。历史迁移若只有已提交或已计算结果，可保留 started_at=NULL、attempt_no=NULL，并使用登记 legacy source_system + migration-only:typed-JCS UUIDv5 锚点；迁移清单必须保存公式、哈希和非来源观察标志。result-only 响应固定 SUBMITTED、validation_result=SOURCE_ANSWERS_UNAVAILABLE；它不等于证明完整问卷答案存在。';
COMMENT ON COLUMN public."mkt_survey_response"."survey_response_id" IS '作答ID。存放：一次问卷尝试稳定身份。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：ace1b145-5557-5c8a-a68a-98c3c0e0a8d7。';
COMMENT ON COLUMN public."mkt_survey_response"."campaign_member_id" IS '活动会员ID。存放：作答所属会员参与。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：无；键/连接：外键->mkt_campaign_member.campaign_member_id（WITH_TABLE）；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：7e810e39-f83d-5a4c-8626-de67f132680f。';
COMMENT ON COLUMN public."mkt_survey_response"."source_system_id" IS '来源系统ID。存放：外部作答ID所属的来源命名空间；纯内部首次作答也登记 HBTI 应用来源。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：无；键/连接：外键->app_source_system.source_system_id（WITH_TABLE）；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：7996d63a-5925-5972-9ea2-b51d0882c497。';
COMMENT ON COLUMN public."mkt_survey_response"."source_response_id" IS '来源作答或迁移锚点ID。存放：真实作答保存来源 attempt_id；只有历史 result-only 迁移允许保存 migration-only:<typed-JCS UUIDv5> 锚点，并在迁移清单标明它不是来源观察。；作用：跨抓取和迁移实现幂等；迁移锚点不得冒充来源作答尝试，也不得据此反推答案。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：migration-only:3e1d9b19-31f4-5a6c-b5dd-27d40c61c674。';
COMMENT ON COLUMN public."mkt_survey_response"."attempt_no" IS '尝试次数。存放：真实来源作答在同一参与中的正整数尝试序号；只有没有来源作答事实的 result-only 历史迁移锚点为空。；作用：保留真实重试而非覆盖，并让无作答事实的迁移记录保持未知。；类型：integer；允许空：是；默认值：无；键/连接：无；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：1。';
COMMENT ON COLUMN public."mkt_survey_response"."started_at" IS '开始时间。存放：本次作答开始时间；历史终态记录未保存开始时点时可为空。；作用：完成时长；缺失时保持未知，不能用访问类别或结果时间倒推。；类型：timestamptz；允许空：是；默认值：无；键/连接：无；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：2026-08-06T11:00:00+08:00。';
COMMENT ON COLUMN public."mkt_survey_response"."submitted_at" IS '提交时间。存放：会员提交本次答案的时间。；作用：完成判定。；类型：timestamptz；允许空：是；默认值：无；键/连接：无；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：2026-08-06T11:05:00+08:00。';
COMMENT ON COLUMN public."mkt_survey_response"."status" IS '作答状态。存放：IN_PROGRESS、SUBMITTED、VALIDATED、REJECTED 或 ABANDONED。；作用：只有 VALIDATED 进入正式活动分析。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：VALIDATED。';
COMMENT ON COLUMN public."mkt_survey_response"."validation_result" IS '校验结果。存放：必答题、选项和重复提交检查。；作用：解释拒绝或部分作答。；类型：jsonb；允许空：否；默认值：''{}''::jsonb；键/连接：无；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：{"required_complete":true}。';
COMMENT ON COLUMN public."mkt_survey_response"."client_context" IS '客户端上下文。存放：非敏感的应用版本、语言和流程版本。；作用：排查交互问题；不得保存IP或设备指纹。；类型：jsonb；允许空：否；默认值：''{}''::jsonb；键/连接：无；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：{"app_version":"1.3"}。';
COMMENT ON COLUMN public."mkt_survey_response"."created_at" IS '创建时间。存放：该行首次写入数据库的绝对时间。；作用：用于审计写入先后、排查延迟；不能代替业务发生时间。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：2026-08-09T10:30:00+08:00。';
COMMENT ON COLUMN public."mkt_survey_response"."updated_at" IS '最后更新时间。存放：该行最后一次被允许修改的绝对时间。；作用：用于增量同步和并发检查；事实发生时间仍应使用专门字段。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：HBTI应用 / 会员提交；敏感级别：none；示例：2026-08-09T11:05:00+08:00。';
COMMENT ON CONSTRAINT "pk_mkt_survey_response__survey_response_id" ON public."mkt_survey_response" IS 'Primary key for the declared one-row grain of mkt_survey_response.';
COMMENT ON CONSTRAINT "uq_mkt_survey_response__campaign_member_id__attempt_no" ON public."mkt_survey_response" IS 'Declared NULLS NOT DISTINCT business key on mkt_survey_response (campaign_member_id, attempt_no).';
COMMENT ON CONSTRAINT "uq_mkt_survey_response__source_system_id__source_response_id" ON public."mkt_survey_response" IS 'Declared ordinary UNIQUE business key on mkt_survey_response (source_system_id, source_response_id).';
COMMENT ON CONSTRAINT "ck_mkt_survey_response__table__01" ON public."mkt_survey_response" IS 'Fail-closed model CHECK table#1: started_at IS NOT NULL OR (submitted_at IS NOT NULL AND status IN (''SUBMITTED'',''VALIDATED'',''REJECTED''))';
COMMENT ON CONSTRAINT "ck_mkt_survey_response__attempt_no__01" ON public."mkt_survey_response" IS 'Fail-closed model CHECK field:attempt_no#1: attempt_no IS NULL OR attempt_no > 0';
COMMENT ON CONSTRAINT "ck_mkt_survey_response__status__01" ON public."mkt_survey_response" IS 'Fail-closed model CHECK field:status#1: status IN (''IN_PROGRESS'',''SUBMITTED'',''VALIDATED'',''REJECTED'',''ABANDONED'')';
COMMENT ON TABLE public."mkt_survey_result" IS '问卷测评结果。用途：保存一次问卷作答锚点经具体算法版本计算或由历史来源迁入的 HBTI 类型及其他测评结果；历史结果可能缺少原答案，不能冒充可复算。；一行粒度：问卷作答 × 结果类型 × 算法版本一行；写入者：HBTI结果计算服务；读取者：HBTI、财务网站、分析/BI；来源：已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；生命周期：CORE_MIGRATION；变更策略：APPEND_ONLY；保留：按活动分析与会员隐私政策保留；删除联系信息不应破坏去标识结果统计。备注：结果是不可变事实，不反写 pos_member 当前列。只有存在真实答案且 input_sha256 非空的结果才可称为可复算；历史 result-only 迁移必须使用 quality_status=''INCOMPLETE_INPUT''、input_sha256=NULL 和明确的历史算法版本，且不得反推答案。算法重跑追加新 algorithm_version；当前业务结果由 campaign_version.result_algorithm_version 明确选择，不回写旧结果为 SUPERSEDED。若新算法要改变会员展示或奖励规则，必须发布新活动版本。';
COMMENT ON COLUMN public."mkt_survey_result"."survey_result_id" IS '测评结果ID。存放：一次问卷测评结果稳定主键。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：eb38ddbe-1657-5c5e-95a2-d2466e3a2a17。';
COMMENT ON COLUMN public."mkt_survey_result"."survey_response_id" IS '作答ID。存放：产生该结果或承接历史结果的问卷作答锚点；不自动证明答案完整。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：无；键/连接：外键->mkt_survey_response.survey_response_id（WITH_TABLE）；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：ace1b145-5557-5c8a-a68a-98c3c0e0a8d7。';
COMMENT ON COLUMN public."mkt_survey_result"."result_type" IS '结果类型。存放：HBTI_PROFILE 或未来批准的其他测评类型。；作用：同一作答可以产生不同业务定义的结果，但不可混用。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：HBTI_PROFILE。';
COMMENT ON COLUMN public."mkt_survey_result"."result_code" IS '结果代码。存放：算法输出的稳定类别代码；现有 hbti_code 迁入此列。；作用：支持活动分群和历史分析，不依赖颜色或展示名称。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：HBTI_DARK_EXPLORER。';
COMMENT ON COLUMN public."mkt_survey_result"."result_label" IS '结果展示名称。存放：计算时面向用户显示的结果名称快照。；作用：保留当时文案；分析连接使用 result_code。；类型：text；允许空：是；默认值：无；键/连接：无；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：Dark Explorer。';
COMMENT ON COLUMN public."mkt_survey_result"."result_color" IS '结果展示颜色。存放：计算时使用的颜色代码或名称快照。；作用：重现 HBTI 结果页，不作为结果身份。；类型：text；允许空：是；默认值：无；键/连接：无；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：#5A3825。';
COMMENT ON COLUMN public."mkt_survey_result"."algorithm_version" IS '结果算法版本。存放：将答案转换为 result_code 的批准算法版本。；作用：算法修改后可以重算并与旧结果并存。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：hbti-score-v2。';
COMMENT ON COLUMN public."mkt_survey_result"."input_sha256" IS '输入答案校验值。存放：按固定顺序规范化真实答案后的 SHA-256；历史来源没有答案时为空。；作用：有值时证明结果对应哪组答案；不得从结果字段反推伪造答案哈希。；类型：char(64)；允许空：是；默认值：无；键/连接：无；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：a91f...64位十六进制。';
COMMENT ON COLUMN public."mkt_survey_result"."result_dimensions" IS '结果维度。存放：算法输出的分数、维度或解释标签。；作用：保存可扩展测评明细；稳定主类别仍使用 result_code。；类型：jsonb；允许空：否；默认值：''{}''::jsonb；键/连接：无；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：{"chocolate":0.82,"adventure":0.64}。';
COMMENT ON COLUMN public."mkt_survey_result"."quality_status" IS '结果质量状态。存放：VALID、INCOMPLETE_INPUT、ALGORITHM_ERROR 或 REJECTED。；作用：只有 VALID 且算法版本等于 campaign_version.result_algorithm_version 的结果可触发正式分群或奖励。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：VALID。';
COMMENT ON COLUMN public."mkt_survey_result"."calculated_at" IS '计算时间。存放：该算法完成结果计算的绝对时间。；作用：排序重算并审计延迟。；类型：timestamptz；允许空：否；默认值：无；键/连接：无；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：2026-08-06T11:05:02+08:00。';
COMMENT ON COLUMN public."mkt_survey_result"."source_system_id" IS '历史来源系统ID。存放：迁移既有结果时标明旧结果ID所属命名空间；本系统新计算结果为空。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：是；默认值：无；键/连接：外键->app_source_system.source_system_id（WITH_TABLE）；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：7996d63a-5925-5972-9ea2-b51d0882c497。';
COMMENT ON COLUMN public."mkt_survey_result"."source_result_id" IS '历史来源结果ID。存放：迁移现有 HBTI 结果时保存旧记录稳定标识；新结果可为空。；作用：旧新结果逐行核对并保证幂等。；类型：text；允许空：是；默认值：无；键/连接：无；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：internal；示例：fact_hbti_response:8812。';
COMMENT ON COLUMN public."mkt_survey_result"."created_at" IS '创建时间。存放：该行首次写入数据库的绝对时间。；作用：用于审计写入先后、排查延迟；不能代替业务发生时间。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：HBTI结果计算服务 / 已验证问卷答案、批准的评分算法或明确标记不完整的历史结果；敏感级别：none；示例：2026-08-09T10:30:00+08:00。';
COMMENT ON CONSTRAINT "pk_mkt_survey_result__survey_result_id" ON public."mkt_survey_result" IS 'Primary key for the declared one-row grain of mkt_survey_result.';
COMMENT ON CONSTRAINT "uq_mkt_survey_result__survey_response_id__result_typ_07b177b353" ON public."mkt_survey_result" IS 'Declared ordinary UNIQUE business key on mkt_survey_result (survey_response_id, result_type, algorithm_version).';
COMMENT ON CONSTRAINT "uq_mkt_survey_result__source_system_id__source_result_id" ON public."mkt_survey_result" IS 'Declared NULLS DISTINCT business key on mkt_survey_result (source_system_id, source_result_id).';
COMMENT ON CONSTRAINT "ck_mkt_survey_result__table__01" ON public."mkt_survey_result" IS 'Fail-closed model CHECK table#1: (source_system_id IS NULL) = (source_result_id IS NULL)';
COMMENT ON CONSTRAINT "ck_mkt_survey_result__table__02" ON public."mkt_survey_result" IS 'Fail-closed model CHECK table#2: input_sha256 IS NOT NULL OR quality_status = ''INCOMPLETE_INPUT''';
COMMENT ON CONSTRAINT "ck_mkt_survey_result__quality_status__01" ON public."mkt_survey_result" IS 'Fail-closed model CHECK field:quality_status#1: quality_status IN (''VALID'',''INCOMPLETE_INPUT'',''ALGORITHM_ERROR'',''REJECTED'')';
COMMENT ON TABLE public."msg_conversation" IS '消息会话。用途：统一表示内部助手、候选人 WhatsApp 或会员活动的一段会话，并用类型化外键连接业务对象。；一行粒度：一个渠道会话一行；写入者：BakeryOps消息服务；读取者：BakeryOps、HBTI、分析/BI；来源：WhatsApp、应用聊天或活动入口；生命周期：CORE_MIGRATION；变更策略：CONTROLLED_UPDATE；保留：业务存续期内保留；归档规则在实施前确认。备注：last_message_at 不重复保存；待跟进排序从 msg_message.occurred_at 的最大值派生并按性能证据决定是否建立物化索引视图。';
COMMENT ON COLUMN public."msg_conversation"."conversation_id" IS '会话ID。存放：跨消息和状态稳定的会话身份。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：none；示例：9cd2ab24-1a32-53ab-acaf-3e122829c899。';
COMMENT ON COLUMN public."msg_conversation"."channel_code" IS '渠道代码。存放：WHATSAPP、WEB_CHAT、LARK 或 OTHER。；作用：路由发送和解析。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：none；示例：WHATSAPP。';
COMMENT ON COLUMN public."msg_conversation"."external_conversation_id" IS '外部会话ID。存放：渠道提供的稳定会话或号码哈希标识。；作用：同步幂等；不得保存明文手机号作为主键。；类型：text；允许空：是；默认值：无；键/连接：无；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：restricted；示例：wa_hash_...。';
COMMENT ON COLUMN public."msg_conversation"."application_id" IS '候选申请ID。存放：招聘会话对应申请；不适用为空。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：是；默认值：无；键/连接：外键->hr_application.application_id（WITH_TABLE）；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：none；示例：3564ea14-b3b1-590c-b1a9-1e4b50e3e6c1。';
COMMENT ON COLUMN public."msg_conversation"."person_id" IS '人员ID。存放：内部或候选人会话对应自然人；不适用为空。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：是；默认值：无；键/连接：外键->hr_person.person_id（WITH_TABLE）；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：none；示例：974372c0-eeaf-573e-b810-7959c45598c9。';
COMMENT ON COLUMN public."msg_conversation"."member_id" IS '会员ID。存放：会员活动会话对应会员；不适用为空。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：是；默认值：无；键/连接：外键->pos_member.member_id（WITH_TABLE）；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：none；示例：ca70f98b-3820-5620-9a6b-71b5098f4e17。';
COMMENT ON COLUMN public."msg_conversation"."app_user_id" IS '应用账号ID。存放：内部用户助手会话对应账号；不适用为空。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：是；默认值：无；键/连接：外键->app_user.user_id（WITH_TABLE）；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：none；示例：4fd6b173-c818-5b7b-8d90-254f85e85ad7。';
COMMENT ON COLUMN public."msg_conversation"."status" IS '会话状态。存放：OPEN、WAITING_USER、WAITING_AGENT、CLOSED、OPTED_OUT 或 BLOCKED。；作用：路由和合规。；类型：text；允许空：否；默认值：''OPEN''；键/连接：无；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：none；示例：WAITING_USER。';
COMMENT ON COLUMN public."msg_conversation"."opened_at" IS '开始时间。存放：会话首次创建时间。；作用：响应时长。；类型：timestamptz；允许空：否；默认值：无；键/连接：无；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：none；示例：2026-08-09T10:00:00+08:00。';
COMMENT ON COLUMN public."msg_conversation"."closed_at" IS '关闭时间。存放：会话结束时间。；作用：生命周期。；类型：timestamptz；允许空：是；默认值：无；键/连接：无；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：none；示例：2026-08-09T10:30:00+08:00。';
COMMENT ON COLUMN public."msg_conversation"."created_at" IS '创建时间。存放：该行首次写入数据库的绝对时间。；作用：用于审计写入先后、排查延迟；不能代替业务发生时间。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：none；示例：2026-08-09T10:30:00+08:00。';
COMMENT ON COLUMN public."msg_conversation"."updated_at" IS '最后更新时间。存放：该行最后一次被允许修改的绝对时间。；作用：用于增量同步和并发检查；事实发生时间仍应使用专门字段。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：BakeryOps消息服务 / WhatsApp、应用聊天或活动入口；敏感级别：none；示例：2026-08-09T11:05:00+08:00。';
COMMENT ON CONSTRAINT "pk_msg_conversation__conversation_id" ON public."msg_conversation" IS 'Primary key for the declared one-row grain of msg_conversation.';
COMMENT ON CONSTRAINT "uq_msg_conversation__channel_code__external_conversation_id" ON public."msg_conversation" IS 'Declared NULLS DISTINCT business key on msg_conversation (channel_code, external_conversation_id).';
COMMENT ON CONSTRAINT "ck_msg_conversation__table__01" ON public."msg_conversation" IS 'Fail-closed model CHECK table#1: closed_at IS NULL OR closed_at >= opened_at';
COMMENT ON CONSTRAINT "ck_msg_conversation__table__02" ON public."msg_conversation" IS 'Fail-closed model CHECK table#2: num_nonnulls(application_id, person_id, member_id, app_user_id) >= 1';
COMMENT ON CONSTRAINT "ck_msg_conversation__channel_code__01" ON public."msg_conversation" IS 'Fail-closed model CHECK field:channel_code#1: channel_code IN (''WHATSAPP'',''WEB_CHAT'',''LARK'',''OTHER'')';
