COMMENT ON CONSTRAINT "ck_ops_calendar_event__event_type__01" ON public."ops_calendar_event" IS 'Fail-closed model CHECK field:event_type#1: event_type IN (''PUBLIC_HOLIDAY'',''SCHOOL_HOLIDAY'',''EVENT'',''CLOSURE'')';
