COMMENT ON CONSTRAINT "ck_ops_location__table__01" ON public."ops_location" IS 'Fail-closed model CHECK table#1: closed_on IS NULL OR opened_on IS NULL OR closed_on >= opened_on';
COMMENT ON CONSTRAINT "ck_ops_location__table__02" ON public."ops_location" IS 'Fail-closed model CHECK table#2: location_id <> ''00000000-0000-0000-0000-000000000000''';
COMMENT ON CONSTRAINT "ck_ops_location__area_code__01" ON public."ops_location" IS 'Fail-closed model CHECK field:area_code#1: area_code IS NULL OR area_code ~ ''^[A-Z][A-Z0-9_-]{1,63}$''';
COMMENT ON CONSTRAINT "ck_ops_location__location_type__01" ON public."ops_location" IS 'Fail-closed model CHECK field:location_type#1: location_type IN (''STORE'',''KITCHEN'',''WAREHOUSE'',''OFFICE'',''HYBRID'')';
COMMENT ON CONSTRAINT "ck_ops_location__status__01" ON public."ops_location" IS 'Fail-closed model CHECK field:status#1: status IN (''PLANNED'',''ACTIVE'',''SUSPENDED'',''CLOSED'')';
COMMENT ON TABLE public."ops_location_source_identity" IS '地点来源身份映射。用途：把 RES、Lark、财务模板等外部地点编号映射到统一 location_id，并保留有效期。；一行粒度：来源系统 × 外部地点ID × 有效期一行；写入者：BakeryOps 主数据审核；读取者：所有项目；来源：外部来源地点目录与人工证据；生命周期：CORE_MIGRATION；变更策略：CONTROLLED_UPDATE；保留：业务存续期内保留；归档规则在实施前确认。备注：RES 可将组织ID放入 source_container_id、shop ID 放入 source_location_id；Lark 地点专属 Bitable 映射把 Base app_token 放入 source_container_id、table_id 放入 source_location_id。两者都是可公开定位的对象ID，真实 app_secret/access_token 只能放密钥管理。evidence 只保存批准依据，不承载运行配置字段。';
COMMENT ON COLUMN public."ops_location_source_identity"."location_source_identity_id" IS '映射ID。存放：一次地点来源映射稳定主键。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：3b4b75a6-5944-5007-904f-323fde6b5087。';
COMMENT ON COLUMN public."ops_location_source_identity"."location_id" IS '地点ID。存放：映射后的企业统一地点。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：无；键/连接：外键->ops_location.location_id（WITH_TABLE）；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：23e9d2d4-f525-5e85-9e18-ad25aadb718c。';
COMMENT ON COLUMN public."ops_location_source_identity"."source_system_id" IS '来源系统ID。存放：提供外部地点编号的来源系统。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：无；键/连接：外键->app_source_system.source_system_id（WITH_TABLE）；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：7996d63a-5925-5972-9ea2-b51d0882c497。';
COMMENT ON COLUMN public."ops_location_source_identity"."source_container_id" IS '来源容器ID。存放：外部地点标识所在的组织、应用、Base 或其他命名空间原始ID；来源没有容器层时为空。；作用：避免只在各自容器内唯一的地点/表ID发生冲突；这是公开对象标识，不是登录密钥。；类型：text；允许空：是；默认值：无；键/连接：无；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：QkgDblq0qaLpRhsoWCpjHIoqpvb。';
COMMENT ON COLUMN public."ops_location_source_identity"."source_location_id" IS '外部地点ID。存放：来源系统在 source_container_id 范围内给出的地点、门店或地点专属集合标识，原样保存。；作用：与来源系统和可选容器共同构成来源身份，不能用来源名称代替。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：shop_104883。';
COMMENT ON COLUMN public."ops_location_source_identity"."source_location_name" IS '外部地点名称。存放：映射时来源显示的地点名称快照。；作用：仅作证据和人工核对，不参与连接。；类型：text；允许空：是；默认值：无；键/连接：无；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：吉隆坡Pavilion门店。';
COMMENT ON COLUMN public."ops_location_source_identity"."valid_from" IS '生效时间。存放：该映射开始有效的时间。；作用：处理来源编号复用或组织调整。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：2025-11-01T00:00:00+08:00。';
COMMENT ON COLUMN public."ops_location_source_identity"."valid_to" IS '失效时间。存放：该映射停止有效的时间。；作用：历史事实仍按发生时的有效映射连接。；类型：timestamptz；允许空：是；默认值：无；键/连接：无；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：2027-01-01T00:00:00+08:00。';
COMMENT ON COLUMN public."ops_location_source_identity"."mapping_status" IS '映射状态。存放：CONFIRMED、PENDING 或 REJECTED。；作用：只有 CONFIRMED 可进入正式跨域分析。；类型：text；允许空：否；默认值：''PENDING''；键/连接：无；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：CONFIRMED。';
COMMENT ON COLUMN public."ops_location_source_identity"."evidence" IS '映射证据。存放：人工确认所依据的来源 URL、截图哈希或业务说明。；作用：禁止无证据按名称猜匹配。；类型：jsonb；允许空：否；默认值：''{}''::jsonb；键/连接：无；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：{"reason":"same RES shop id"}。';
COMMENT ON COLUMN public."ops_location_source_identity"."created_by_user_id" IS '创建账号。存放：触发该次人工或受控系统写入的应用账号。自动任务可以为空并由 job_run_id 追踪。；作用：区分谁确认了业务事实与哪个服务实际执行 SQL。；类型：uuid；允许空：是；默认值：无；键/连接：外键->app_user.user_id（WITH_TABLE）；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：internal；示例：018f7f12-7c40-7dc1-a2ac-4a7924c60b21。';
COMMENT ON COLUMN public."ops_location_source_identity"."created_at" IS '创建时间。存放：该行首次写入数据库的绝对时间。；作用：用于审计写入先后、排查延迟；不能代替业务发生时间。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：2026-08-09T10:30:00+08:00。';
COMMENT ON COLUMN public."ops_location_source_identity"."updated_at" IS '最后更新时间。存放：该行最后一次被允许修改的绝对时间。；作用：用于增量同步和并发检查；事实发生时间仍应使用专门字段。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：BakeryOps 主数据审核 / 外部来源地点目录与人工证据；敏感级别：none；示例：2026-08-09T11:05:00+08:00。';
COMMENT ON CONSTRAINT "pk_ops_location_source_identity__location_source_identity_id" ON public."ops_location_source_identity" IS 'Primary key for the declared one-row grain of ops_location_source_identity.';
COMMENT ON CONSTRAINT "uq_ops_location_source_identity__source_system_id__s_0293074e34" ON public."ops_location_source_identity" IS 'Declared NULLS NOT DISTINCT business key on ops_location_source_identity (source_system_id, source_container_id, source_location_id, valid_from).';
COMMENT ON CONSTRAINT "ck_ops_location_source_identity__table__01" ON public."ops_location_source_identity" IS 'Fail-closed model CHECK table#1: valid_to IS NULL OR valid_to > valid_from';
COMMENT ON CONSTRAINT "ck_ops_location_source_identity__table__02" ON public."ops_location_source_identity" IS 'Fail-closed model CHECK table#2: source_container_id IS NULL OR source_container_id <> ''''';
COMMENT ON CONSTRAINT "ck_ops_location_source_identity__mapping_status__01" ON public."ops_location_source_identity" IS 'Fail-closed model CHECK field:mapping_status#1: mapping_status IN (''CONFIRMED'',''PENDING'',''REJECTED'')';
COMMENT ON CONSTRAINT "ex_ops_location_source_identity__confirmed_period" ON public."ops_location_source_identity" IS 'Approved non-overlap contract: NO_OVERLAP(source_system_id, COALESCE(source_container_id, ''''), source_location_id, tstzrange(valid_from, valid_to, ''[)'')) WHERE mapping_status = ''CONFIRMED''';
COMMENT ON TABLE public."ops_operational_event" IS '运营突发事件。用途：记录停电、设备故障、人流异常、促销或其他当日突发情况及人工证据。；一行粒度：一个地点的一次连续运营事件一行；写入者：门店或区域运营；读取者：BakeryOps、分析/BI；来源：人工确认；部分事件可由系统建议；生命周期：CORE_MIGRATION；变更策略：CONTROLLED_UPDATE_UNTIL_TERMINAL；保留：业务存续期内保留；归档规则在实施前确认。备注：OPEN 阶段允许补充证据和结束时间；CONFIRMED、RESOLVED 或 REJECTED 后事件冻结，更正追加新事件或审计冲销，不原地改写历史。';
COMMENT ON COLUMN public."ops_operational_event"."operational_event_id" IS '运营事件ID。存放：一次运营突发稳定主键。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：gen_random_uuid()；键/连接：主键；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：79df84ae-cf8c-5dd1-a83b-106687f641c6。';
COMMENT ON COLUMN public."ops_operational_event"."location_id" IS '地点ID。存放：事件发生地点。；作用：作为稳定连接键，避免使用名称、手机号或外部编号跨模块关联。；类型：uuid；允许空：否；默认值：无；键/连接：外键->ops_location.location_id（WITH_TABLE）；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：23e9d2d4-f525-5e85-9e18-ad25aadb718c。';
COMMENT ON COLUMN public."ops_operational_event"."event_type" IS '事件类型。存放：POWER_OUTAGE、EQUIPMENT_FAILURE、PROMOTION、FOOTFALL_SURGE、STAFF_SHORTAGE 或 OTHER。；作用：支持标准化影响分析。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：EQUIPMENT_FAILURE。';
COMMENT ON COLUMN public."ops_operational_event"."event_title" IS '事件标题。存放：简短可读的事件概述。；作用：供复盘和时间线展示。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：烤箱2号故障。';
COMMENT ON COLUMN public."ops_operational_event"."started_at" IS '开始时间。存放：事件实际或估计开始时间。；作用：判断受影响销售和生产时段。；类型：timestamptz；允许空：否；默认值：无；键/连接：无；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：2026-08-08T13:20:00+08:00。';
COMMENT ON COLUMN public."ops_operational_event"."ended_at" IS '结束时间。存放：事件恢复时间；仍持续时为空。；作用：计算影响持续时间。；类型：timestamptz；允许空：是；默认值：无；键/连接：无；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：2026-08-08T15:10:00+08:00。';
COMMENT ON COLUMN public."ops_operational_event"."impact_direction" IS '影响方向。存放：INCREASE、DECREASE、MIXED 或 UNKNOWN。；作用：区分需求上涨和产能下降。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：DECREASE。';
COMMENT ON COLUMN public."ops_operational_event"."impact_summary" IS '影响说明。存放：对产能、销售、人员或服务的可读说明。；作用：保留人工判断但不替代量化事实。；类型：text；允许空：否；默认值：无；键/连接：无；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：黑巧产能下降约30%。';
COMMENT ON COLUMN public."ops_operational_event"."evidence" IS '事件证据。存放：照片链接哈希、设备工单或销售差异等脱敏证据。；作用：支持审核。；类型：jsonb；允许空：否；默认值：''{}''::jsonb；键/连接：无；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：{"ticket":"EQ-20260808-2"}。';
COMMENT ON COLUMN public."ops_operational_event"."status" IS '事件状态。存放：OPEN、CONFIRMED、RESOLVED 或 REJECTED。；作用：只有确认事件影响正式复盘。；类型：text；允许空：否；默认值：''OPEN''；键/连接：无；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：CONFIRMED。';
COMMENT ON COLUMN public."ops_operational_event"."created_by_user_id" IS '创建账号。存放：触发该次人工或受控系统写入的应用账号。自动任务可以为空并由 job_run_id 追踪。；作用：区分谁确认了业务事实与哪个服务实际执行 SQL。；类型：uuid；允许空：是；默认值：无；键/连接：外键->app_user.user_id（WITH_TABLE）；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：internal；示例：018f7f12-7c40-7dc1-a2ac-4a7924c60b21。';
COMMENT ON COLUMN public."ops_operational_event"."created_at" IS '创建时间。存放：该行首次写入数据库的绝对时间。；作用：用于审计写入先后、排查延迟；不能代替业务发生时间。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：2026-08-09T10:30:00+08:00。';
COMMENT ON COLUMN public."ops_operational_event"."updated_at" IS '最后更新时间。存放：该行最后一次被允许修改的绝对时间。；作用：用于增量同步和并发检查；事实发生时间仍应使用专门字段。；类型：timestamptz；允许空：否；默认值：now()；键/连接：无；写入来源：门店或区域运营 / 人工确认；部分事件可由系统建议；敏感级别：none；示例：2026-08-09T11:05:00+08:00。';
COMMENT ON CONSTRAINT "pk_ops_operational_event__operational_event_id" ON public."ops_operational_event" IS 'Primary key for the declared one-row grain of ops_operational_event.';
COMMENT ON CONSTRAINT "ck_ops_operational_event__table__01" ON public."ops_operational_event" IS 'Fail-closed model CHECK table#1: ended_at IS NULL OR ended_at > started_at';
COMMENT ON CONSTRAINT "ck_ops_operational_event__event_type__01" ON public."ops_operational_event" IS 'Fail-closed model CHECK field:event_type#1: event_type IN (''POWER_OUTAGE'',''EQUIPMENT_FAILURE'',''PROMOTION'',''FOOTFALL_SURGE'',''STAFF_SHORTAGE'',''OTHER'')';
COMMENT ON CONSTRAINT "ck_ops_operational_event__impact_direction__01" ON public."ops_operational_event" IS 'Fail-closed model CHECK field:impact_direction#1: impact_direction IN (''INCREASE'',''DECREASE'',''MIXED'',''UNKNOWN'')';
