COMMENT ON CONSTRAINT "uq_pos_item_waste__pos_ingest_batch_id__source_waste_id" ON public."pos_item_waste" IS 'Declared NULLS DISTINCT business key on pos_item_waste (pos_ingest_batch_id, source_waste_id).';
